                            case 0x9E: // EX9E: Skip if key VX pressed
                                this.PC += (this.keys[this.V[x] & 0xF]) ? 4 : 2;
                                break;
                            case 0xA1: // EXA1: Skip if key VX not pressed
                                this.PC += (!this.keys[this.V[x] & 0xF]) ? 4 : 2;
                                break;
                            default:
                                this.PC += 2;
                                break;
                        }
                        break;

                    case 0xF000:
