            }

            decodeInstruction(opcode) {
                const x = (opcode >> 8) & 0x0F;
                const y = (opcode >> 4) & 0x0F;
                const n = opcode & 0x0F;
                const nn = opcode & 0xFF;
                const nnn = opcode & 0x0FFF;

                switch (opcode & 0xF000) {
                    case 0x0000:
                        if (opcode === 0x00E0) return "CLR";
                        if (opcode === 0x00EE) return "RET";
                        return `SYS 0x${nnn.toString(16).toUpperCase()}`;
                    case 0x1000: return `JP 0x${nnn.toString(16).toUpperCase()}`;
                    case 0x2000: return `CALL 0x${nnn.toString(16).toUpperCase()}`;
                    case 0x3000: return `SE V${x}, 0x${nn.toString(16).toUpperCase()}`;
                    case 0x4000: return `SNE V${x}, 0x${nn.toString(16).toUpperCase()}`;
                    case 0x5000: return `SE V${x}, V${y}`;
                    case 0x6000: return `LD V${x}, 0x${nn.toString(16).toUpperCase()}`;
                    case 0x7000: return `ADD V${x}, 0x${nn.toString(16).toUpperCase()}`;
                    case 0x8000:
                        switch (n) {
                            case 0x0: return `LD V${x}, V${y}`;
                            case 0x1: return `OR V${x}, V${y}`;
                            case 0x2: return `AND V${x}, V${y}`;
                            case 0x3: return `XOR V${x}, V${y}`;
                            case 0x4: return `ADD V${x}, V${y}`;
                            case 0x5: return `SUB V${x}, V${y}`;
                            case 0x6: return `SHR V${x}`;
                            case 0x7: return `SUBN V${x}, V${y}`;
                            case 0xE: return `SHL V${x}`;
