        // Demo ROM: A simple program that draws a sprite and moves it with keys
        // Assembly:
        // 0200  60 05    LD V0, 0x05     ; V0 = 5 (sprite height)
        // 0202  61 20    LD V1, 0x20     ; V1 = 32 (x position)
        // 0204  62 10    LD V2, 0x10     ; V2 = 16 (y position)
        // 0206  63 08    LD V3, 0x08     ; V3 = 8 (sprite data start)
