            0x63, 0x08,    // 0206: LD V3, 0x08
            0xA3, 0x08,    // 0208: LD I, 0x308
            0xD1, 0x25,    // 020A: DRW V1, V2, 5
            0x60, 0x00,    // 020C: LD V0, 0x00
            0xE0, 0x9E,    // 020E: SKP V0
            0x12, 0x18,    // 0210: JP 0x218
            0x61, 0x21,    // 0212: LD V1, 0x21
            0x12, 0x0A,    // 0214: JP 0x20A
            0x00, 0x00,    // 0216: (padding)
            // Sprite data at 0x308
            0x00,          // 0308: byte 0
            0x18,          // 0309: byte 1 (00011000)
            0x3C,          // 030A: byte 2 (00111100)
            0x7E,          // 030B: byte 3 (01111110)
            0x3C           // 030C: byte 4 (00111100)
        ]);

        // UI and Event Handling
        const chip8 = new Chip8();
        const canvas = document.getElementById('display');
        const ctx = canvas.getContext('2d');
        const keypad = document.getElementById('keypad');
        const keys = document.querySelectorAll('.key');

        // Keyboard mapping: CHIP-8 keys to keyboard keys
        const keyMap = {
            '1': 'Key1', '2': 'Key2', '3': 'Key3', 'C': 'Key4',
            '4': 'Key5', '5': 'Key6', '6': 'Key7', 'D': 'Key8',
            '7': 'Key9', '8': 'Key0', '9': 'Minus', 'E': 'Equal',
            'A': 'ArrowLeft', '0': 'ArrowDown', 'B': 'ArrowUp', 'F': 'ArrowRight'
        };

        const reverseKeyMap = {};
        for (const [chip8Key, keyboardKey] of Object.entries(keyMap)) {
            reverseKeyMap[keyboardKey] = parseInt(chip8Key, 16);
        }

        let isRunning = false;
        let stepCount = 10;
        let animationId = null;

        function drawDisplay() {
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = '#00ff88';
            for (let y = 0; y < 32; y++) {
                for (let x = 0; x < 64; x++) {
                    if (chip8.display[y * 64 + x]) {
                        ctx.fillRect(x, y, 1, 1);
                    }
                }
            }
        }

        function updateDebugger(opcode) {
            // Update registers
            const regContainer = document.getElementById('registers');
            regContainer.innerHTML = '';
            for (let i = 0; i < 16; i++) {
                const reg = document.createElement('div');
                reg.className = 'reg';
                reg.innerHTML = `<span class="reg-name">V${i.toString(16).toUpperCase()}: </span><span class="reg-val">${chip8.V[i].toString(16).toUpperCase().padStart(2, '0')}</span>`;
                regContainer.appendChild(reg);
            }

            // Update I and PC
            document.getElementById('regI').textContent = chip8.I.toString(16).toUpperCase().padStart(4, '0');
            document.getElementById('regPC').textContent = chip8.PC.toString(16).toUpperCase().padStart(4, '0');

            // Update stack
            const stackList = document.getElementById('stackList');
            stackList.innerHTML = '';
            document.getElementById('spVal').textContent = chip8.SP;
            for (let i = 0; i < chip8.SP && i < 16; i++) {
                const item = document.createElement('div');
                item.className = 'stack-item';
                item.textContent = `SP[${i}] = 0x${chip8.stack[i].toString(16).toUpperCase().padStart(4, '0')}`;
                stackList.appendChild(item);
            }

            // Update current instruction
            const opcode = (chip8.memory[chip8.PC] << 8) | chip8.memory[chip8.PC + 1];
            const decoded = chip8.decodeInstruction(opcode);
            document.getElementById('currentInstruction').textContent = `${opcode.toString(16).toUpperCase().padStart(4, '0')} ${decoded}`;

            // Update timers
            document.getElementById('delayTimer').textContent = chip8.delayTimer;
            document.getElementById('soundTimer').textContent = chip8.soundTimer;
        }

        function gameLoop() {
            if (!isRunning) return;

            chip8.run(stepCount);
            if (chip8.drawFlag) {
                drawDisplay();
                chip8.drawFlag = false;
            }
            updateDebugger();

            animationId = requestAnimationFrame(gameLoop);
        }

        function updateKeypadDisplay() {
            keys.forEach(key => {
                const chip8Key = key.dataset.key;
                const keyValue = parseInt(chip8Key, 16);
                if (chip8.keys[keyValue]) {
                    key.classList.add('active');
                } else {
                    key.classList.remove('active');
                }
            });
        }

        // Keyboard event handlers
        document.addEventListener('keydown', (e) => {
            if (e.repeat) return;
            const keyboardKey = e.code;
            if (reverseKeyMap[keyboardKey] !== undefined) {
                const chip8Key = reverseKeyMap[keyboardKey];
                chip8.keys[chip8Key] = 1;
                updateKeypadDisplay();
            }
        });

        document.addEventListener('keyup', (e) => {
            const keyboardKey = e.code;
            if (reverseKeyMap[keyboardKey] !== undefined) {
                const chip8Key = reverseKeyMap[keyboardKey];
                chip8.keys[chip8Key] = 0;
                updateKeypadDisplay();
            }
        });

        // Mouse/touch handlers for on-screen keypad
        keys.forEach(key => {
            key.addEventListener('mousedown', (e) => {
                e.preventDefault();
                const chip8Key = parseInt(key.dataset.key, 16);
                chip8.keys[chip8Key] = 1;
                updateKeypadDisplay();
            });

            key.addEventListener('mouseup', (e) => {
                e.preventDefault();
                const chip8Key = parseInt(key.dataset.key, 16);
                chip8.keys[chip8Key] = 0;
                updateKeypadDisplay();
            });

            key.addEventListener('mouseleave', (e) => {
                const chip8Key = parseInt(key.dataset.key, 16);
                chip8.keys[chip8Key] = 0;
                updateKeypadDisplay();
            });

            key.addEventListener('touchstart', (e) => {
                e.preventDefault();
                const chip8Key = parseInt(key.dataset.key, 16);
                chip8.keys[chip8Key] = 1;
                updateKeypadDisplay();
            });

            key.addEventListener('touchend', (e) => {
                e.preventDefault();
                const chip8Key = parseInt(key.dataset.key, 16);
                chip8.keys[chip8Key] = 0;
                updateKeypadDisplay();
            });
        });

        // Control buttons
        document.getElementById('btnRun').addEventListener('click', () => {
            if (!isRunning) {
                isRunning = true;
                document.getElementById('status').textContent = 'Running...';
                document.getElementById('status').className = 'status running';
                gameLoop();
            }
        });

        document.getElementById('btnPause').addEventListener('click', () => {
            isRunning = false;
            if (animationId) {
                cancelAnimationFrame(animationId);
                animationId = null;
            }
            document.getElementById('status').textContent = 'Paused';
            document.getElementById('status').className = 'status paused';
        });

        document.getElementById('btnStep').addEventListener('click', () => {
            isRunning = false;
            if (animationId) {
                cancelAnimationFrame(animationId);
                animationId = null;
            }

            chip8.run(stepCount);
            if (chip8.drawFlag) {
                drawDisplay();
                chip8.drawFlag = false;
            }
            updateDebugger();
            document.getElementById('status').textContent = 'Stepped';
            document.getElementById('status').className = 'status paused';
        });

        document.getElementById('btnReset').addEventListener('click', () => {
            isRunning = false;
            if (animationId) {
                cancelAnimationFrame(animationId);
                animationId = null;
            }

            chip8.reset();
            chip8.loadROM(demoROM);
            drawDisplay();
            updateDebugger();
            document.getElementById('status').textContent = 'Ready - Demo ROM loaded';
            document.getElementById('status').className = 'status running';
        });

        // Speed control
        document.getElementById('speedSlider').addEventListener('input', (e) => {
            stepCount = parseInt(e.target.value);
            document.getElementById('speedValue').textContent = stepCount;
        });

        // File input
        document.getElementById('romFile').addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = (event) => {
                const rom = new Uint8Array(event.target.result);
                chip8.loadROM(rom);
                drawDisplay();
                updateDebugger();
                document.getElementById('status').textContent = `Loaded: ${file.name}`;
                document.getElementById('status').className = 'status paused';
            };
            reader.readAsArrayBuffer(file);
        });

        // Initialize
        chip8.loadROM(demoROM);
        drawDisplay();
        updateDebugger();
    </script>
</body>
</html>
